import { apiClient } from "./client";
import { CreateSalePayload, Sale } from "../types";

/**
 * Fetch sales history (automatically scoped to the current rep's active trip by the backend).
 */
export const fetchSales = async (): Promise<Sale[]> => {
  const response = await apiClient.get<Sale[]>("/api/sales?mine=true");
  return response.data;
};

/**
 * Create a new Point of Sale transaction.
 * Authoritative totals, stock deductions, and invoice numbers are generated by the server.
 */
export const createSale = async (payload: CreateSalePayload): Promise<Sale> => {
  const response = await apiClient.post<Sale>("/api/sales", payload);
  return response.data;
};

/**
 * Fetch a sale by server-generated invoice number.
 * Useful for post-timeout verification or receipt rendering.
 */
export const fetchSaleByInvoice = async (invoiceNo: string): Promise<Sale> => {
  const response = await apiClient.get<Sale>(`/api/sales/invoice/${encodeURIComponent(invoiceNo)}`);
  return response.data;
};

/**
 * Fetch sale details by MongoDB ID.
 */
export const fetchSaleById = async (id: string): Promise<Sale> => {
  const response = await apiClient.get<Sale>(`/api/sales/${id}`);
  return response.data;
};

